        if (!value.includes('.')) return 'Email requires a domain (e.g., example.com)';
        const parts = value.split('@');
        if (parts[0].length === 0) return 'Email cannot start with @';
        return null;
    },
    name: (value) => {
        if (value.length < 2) return 'Name must be at least 2 characters long';
        if (!/^[A-Za-z\s]+$/.test(value)) return 'Name can only contain letters and spaces, no numbers or special characters';
        return null;
    },
    message: (value) => {
        if (value.length < 10) return `Message must be at least 10 characters. You have ${value.length} character(s)`;
        if (value.length > 1000) return `Message is too long. Maximum is 1000 characters. You have ${value.length}`;
        return null;
    }
};

